<script module lang="ts">
/**
 * AppShell.UserCard: the rail’s foot, showing the signed-in user.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/app-shell.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/archetypes/app-shell.module.css'
import Avatar from '../structure/Avatar.svelte'

export interface AppShellUserCardProps {
  /**
   * The first line. Initials and the identity colour are derived from it.
   */
  name: string
  /**
   * The second line, such as an email, a role or the signed-in workspace.
   */
  detail: string
  /**
   * The avatar image.
   */
  src?: string
  /**
   * The control at the row’s end, by convention a Menu, hidden when collapsed.
   */
  end?: Snippet
}
</script>

<script lang="ts">
let { name, detail, src, end }: AppShellUserCardProps = $props()
const joined = joinSlot(undefined, () => ({ name: name }))
const slots = {
  get end() {
    return end
  },
}
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div class={styles.userCard}
    ><Avatar {name} {src} size="md"
    /><span class={styles.userText}
      ><span class={styles.userName}>{name}</span
      ><span class={styles.userDetail}>{detail}</span
    ></span
    >{#if slots.end}<span class={styles.userEnd}>{@render end?.()}</span>{/if
  }</div
>{/if
}{@render joined.end?.()}
